package kz.zani.mobile
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.*
import kotlinx.coroutines.test.*
import kz.zani.mobile.core.*
import kz.zani.mobile.data.*
import kz.zani.mobile.ui.*
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
@OptIn(ExperimentalCoroutinesApi::class)
class InboxPriorityTest {
    private fun fixture(n:String)=javaClass.classLoader!!.getResourceAsStream("fixtures/$n.json")!!.bufferedReader().use {it.readText()}
    private fun context(o:JSONObject)=InboxConversationFilesContext(o.getInt("business"),o.getInt("conversation"),o.getInt("epoch"),o.getInt("revision"))
    private fun files()=APIInboxConversationFilesRepository(FixtureInboxConversationFilesTransport.fromJSON(fixture("inbox-conversation-files")))
    private fun source()=APIInboxPriorityRepository(FixtureInboxPriorityReadTransport.fromJSON(fixture("inbox-priority")))
    private class Held(override val grants:List<SyntheticInboxPriorityGrant>):SyntheticInboxPriorityPort {val attempts=mutableListOf<InboxPriorityAttempt>();val pending=mutableListOf<CompletableDeferred<SyntheticInboxPriorityOutcome>>();override suspend fun execute(a:InboxPriorityAttempt):SyntheticInboxPriorityOutcome {attempts+=a;return CompletableDeferred<SyntheticInboxPriorityOutcome>().also {pending+=it}.await()}}
    @Test fun sharedRawSourceExactBodyAllChoicesAndRetainedUnknown()=runTest {
        val d=JSONObject(fixture("inbox-priority"));val c=context(d.getJSONObject("context"));val rows=d.getJSONArray("source_cases");for(i in 0 until rows.length()){val x=rows.getJSONObject(i);assertEquals(x.getString("name"),x.getBoolean("valid"),InboxPrioritySource.decode(x.getString("response_json"),context(x.getJSONObject("context")))!=null)}
        val f=FixtureInboxPriorityPort.fromJSON(fixture("inbox-priority"));val s=InboxPrioritySource.decode(d.getString("source_json"),c)!!;val auth=f.grants[0].authorization(c)!!;val receipts=d.getJSONArray("receipt_cases")
        for(i in 0 until receipts.length()){val x=receipts.getJSONObject(i);val value=InboxPriorityValue.entries.single {it.wire==x.getString("priority")};val l=InboxPriorityLedger();val a=l.begin(InboxPriorityReview(s,auth,value,1))!!;assertEquals(x.getString("name"),x.getBoolean("valid"),InboxPriorityReceipt.decode(x.getString("response_json"),a)!=null)}
        for(value in InboxPriorityValue.entries){val l=InboxPriorityLedger();val r=InboxPriorityReview(s,auth,value,2);val a=l.begin(r)!!;val body=JSONObject(a.preparedBody());assertEquals(setOf("priority"),body.keys().asSequence().toSet());assertEquals(value.wire,body.getString("priority"));assertTrue(a.query.isEmpty());assertTrue(a.headers.isEmpty());assertNull(l.begin(r));assertFalse(l.acknowledge(auth,l.visible(auth)!!));l.complete(a,f.execute(a));val result=l.visible(auth)!!;assertEquals(InboxPriorityPhase.RESPONSE,result.phase);assertEquals(value.wire,result.result!!.source.priority);assertEquals(s,result.attempt.review.source);assertTrue(l.acknowledge(auth,result))}
        val l=InboxPriorityLedger();val r=InboxPriorityReview(s,auth,InboxPriorityValue.HIGH,3);val a=l.begin(r)!!;l.complete(a,SyntheticInboxPriorityOutcome.Unknown);val u=l.visible(auth)!!;val next=c.copy(epoch=2,revision=2);val na=f.grants[0].authorization(next)!!;val matching=s.copy(context=next,priority="high");assertEquals(u,l.visible(na));assertFalse(l.acknowledge(na,u));assertNull(l.begin(InboxPriorityReview(matching,na,InboxPriorityValue.LOW,4)));assertEquals(a,l.records[0].attempt);val other=SyntheticInboxPriorityGrant(101,901,6002,true).authorization(next)!!;assertNull(l.visible(other));assertTrue(l.blocked(101,901));assertFalse(l.blocked(202,951))
        for(g in listOf(SyntheticInboxPriorityGrant(101,901,5001,false),SyntheticInboxPriorityGrant(202,901,5001,true),SyntheticInboxPriorityGrant(101,951,5001,true),SyntheticInboxPriorityGrant(101,901,0,true)))assertNull(g.authorization(c))
        for(status in listOf(201,400,403,409,500)){val ledger=InboxPriorityLedger();val a=ledger.begin(r)!!;ledger.complete(a,SyntheticInboxPriorityOutcome.Response(status,"{}"));assertEquals(InboxPriorityPhase.UNKNOWN,ledger.visible(auth)!!.phase);assertFalse(ledger.acknowledge(auth,ledger.visible(auth)!!))}
    }
    @Test fun actualParentChoiceReviewBackClearUnknownABAAndDefaultNoPort()=runTest {
        Dispatchers.setMain(StandardTestDispatcher(testScheduler));val f=FixtureInboxPriorityPort.fromJSON(fixture("inbox-priority"));val held=Held(f.grants)
        val read=APIReadRepository(ReadTransport {q->val n=if(q.path=="/api/mobile/v1/inbox/")"inbox-${q.query["business"]}"else "inbox-${q.query["business"]}-${q.path.trimEnd('/').substringAfterLast('/')}";ReadResponse(200,fixture(n))});val m=InboxViewModel(read,files=files(),priorityRead=source(),prioritySubmission=held)
        try {m.load(101,501);runCurrent();m.open(901);runCurrent();val original=m.state.thread;val c=m.fileMetadata!!;m.openFiles(m.filesEntryControl);assertNull(c.selectedPriorityValue);assertFalse(c.canPreparePriority);c.loadPriority(c.control);assertEquals("future é",c.prioritySource!!.priority);assertNull(c.selectedPriorityValue);val old=c.control;c.choosePriority(InboxPriorityValue.HIGH,c.control);val high=c.control;c.clearPriorityChoice(old);assertEquals(InboxPriorityValue.HIGH,c.selectedPriorityValue);c.clearPriorityChoice(high);assertNull(c.selectedPriorityValue);c.choosePriority(InboxPriorityValue.HIGH,c.control);c.preparePriority(c.control);val r=c.priorityReview!!;val ctrl=c.control;c.choosePriority(InboxPriorityValue.LOW,c.control);c.prepareMarker(InboxReadMarkerAction.READ,c.control);c.prepareAssignment(c.control);assertEquals(r,c.priorityReview);assertTrue(c.canSubmitPriority);assertNull(c.markerReview);assertNull(c.assignmentReview);c.backPriority(c.control);assertEquals(InboxPriorityValue.HIGH,c.selectedPriorityValue);m.closeFiles(m.filesPresentationControl);m.openFiles(m.filesEntryControl);assertEquals(InboxPriorityValue.HIGH,c.selectedPriorityValue);assertNull(c.prioritySource);c.loadPriority(c.control);c.preparePriority(c.control);val review=c.priorityReview!!;val control=c.control;val job=launch {c.submitPriority(review,control)};runCurrent();val pending=c.priorityRecord!!;c.submitPriority(review,c.control);c.acknowledgePriority(pending,c.control);assertEquals(1,held.attempts.size);assertTrue(m.conversationCommandsBlocked);assertFalse(c.canLoadMarker);assertFalse(c.canLoadAssignment);held.pending[0].complete(f.execute(held.attempts[0]));job.join();val result=c.priorityRecord!!;assertEquals(InboxPriorityPhase.RESPONSE,result.phase);assertEquals("high",result.result!!.source.priority);assertEquals(original,m.state.thread);c.acknowledgePriority(result,control);assertEquals(result,c.priorityRecord);c.acknowledgePriority(result,c.control);c.choosePriority(InboxPriorityValue.NORMAL,c.control);c.preparePriority(c.control);val ur=c.priorityReview!!;val uc=c.control;val uj=launch {c.submitPriority(ur,uc)};runCurrent();held.pending[1].completeExceptionally(IllegalStateException("synthetic failure"));uj.join();val unknown=c.priorityRecord!!;c.clearPriorityChoice(c.control);c.choosePriority(InboxPriorityValue.LOW,c.control);c.loadPriority(c.control);assertEquals(unknown,c.priorityRecord);assertEquals(InboxPriorityValue.NORMAL,unknown.attempt.review.value);assertFalse(c.canChoosePriority);assertEquals(InboxPriorityValue.NORMAL,c.selectedPriorityValue);m.closeFiles(m.filesPresentationControl);m.load(202,502);runCurrent();m.open(951);runCurrent();m.openFiles(m.filesEntryControl);c.loadPriority(c.control);assertNull(c.priorityRecord);assertNull(c.selectedPriorityValue);m.closeFiles(m.filesPresentationControl);m.load(101,503);runCurrent();m.open(901);runCurrent();m.openFiles(m.filesEntryControl);c.loadPriority(c.control);assertEquals(unknown,c.priorityRecord);assertFalse(c.canChoosePriority)
            val np=InboxConversationFilesModel(files(),priorityRead=source());np.commandsBlocked={false};np.bind(InboxConversationFilesContext(101,901,504,1));np.open(np.control);np.loadPriority(np.control);np.choosePriority(InboxPriorityValue.HIGH,np.control);assertNotNull(np.prioritySource);assertNull(np.selectedPriorityValue)
            val cp=Held(f.grants);val cm=InboxConversationFilesModel(files(),priorityRead=source(),priorityPort=cp);cm.commandsBlocked={false};cm.bind(InboxConversationFilesContext(101,901,505,1));cm.open(cm.control);cm.loadPriority(cm.control);cm.choosePriority(InboxPriorityValue.URGENT,cm.control);cm.preparePriority(cm.control);val cr=cm.priorityReview!!;val cc=cm.control;val cj=launch {cm.submitPriority(cr,cc)};runCurrent();cp.pending[0].complete(SyntheticInboxPriorityOutcome.RejectedWithoutWrite);cj.join();val rejected=cm.priorityRecord!!;assertEquals(InboxPriorityPhase.REJECTED,rejected.phase);cm.acknowledgePriority(rejected,cm.control);cm.preparePriority(cm.control);val xr=cm.priorityReview!!;val xc=cm.control;val xj=launch {cm.submitPriority(xr,xc)};runCurrent();xj.cancelAndJoin();assertEquals(InboxPriorityPhase.UNKNOWN,cm.priorityRecord!!.phase);assertEquals(xr,cm.priorityRecord!!.attempt.review)
        } finally {m.viewModelScope.cancel();Dispatchers.resetMain()}
    }
    @Test fun lateCommandAndSourceKeepNewBusinessChoiceAndControl()=runTest {
        val f=FixtureInboxPriorityPort.fromJSON(fixture("inbox-priority"));val held=Held(f.grants);val ac=InboxConversationFilesContext(101,901,506,1);val bc=InboxConversationFilesContext(202,951,507,1);val m=InboxConversationFilesModel(files(),priorityRead=source(),priorityPort=held);m.commandsBlocked={false};m.bind(ac);m.open(m.control);m.loadPriority(m.control);m.choosePriority(InboxPriorityValue.HIGH,m.control);m.preparePriority(m.control);val r=m.priorityReview!!;val ctrl=m.control;val j=launch {m.submitPriority(r,ctrl)};runCurrent();val a=held.attempts[0];m.close(m.presentation);m.bind(bc);m.open(m.control);m.loadPriority(m.control);m.choosePriority(InboxPriorityValue.LOW,m.control);val before=m.control;val sourceBefore=m.prioritySource;held.pending[0].complete(f.execute(a));j.join();assertEquals(before,m.control);assertEquals(sourceBefore,m.prioritySource);assertEquals(InboxPriorityValue.LOW,m.selectedPriorityValue);assertNull(m.priorityRecord);assertEquals(1,m.retainedPriorityCount)
        val deferred=CompletableDeferred<InboxPrioritySource>();val repo=object:InboxPriorityRepository {override suspend fun source(c:InboxConversationFilesContext)=deferred.await()};val late=InboxConversationFilesModel(files(),priorityRead=repo,priorityPort=f);late.bind(ac);late.open(late.control);val old=late.control;val job=launch {late.loadPriority(old)};runCurrent();late.close(late.presentation);late.bind(bc);late.open(late.control);val newControl=late.control;deferred.complete(source().source(ac));job.join();assertEquals(newControl,late.control);assertNull(late.prioritySource);assertNull(late.selectedPriorityValue);assertFalse(late.priorityLoading)
    }

}
